look.customCSS:
/* ───── 黑白 · 第一批 ───── */
[data-wk="chat"]{background:radial-gradient(ellipse at 85% 30%,rgba(240,205,180,.55),transparent 55%),radial-gradient(ellipse at 15% 80%,rgba(210,205,235,.45),transparent 55%),linear-gradient(180deg,#F2F1EE,#ECE9E6) !important}
[data-wk="body"]{background:transparent !important}

/* 顶栏：一条浮起来的白胶囊 */
[data-wk="chathead"]{background:transparent !important;border-bottom:none !important;box-shadow:none !important;position:relative !important;z-index:5 !important;padding-left:24px !important;padding-right:24px !important}
[data-wk="chathead"]::before{content:"" !important;position:absolute !important;left:12px !important;right:12px !important;top:calc(var(--app-safe-top, 0px) + 4px) !important;bottom:4px !important;border-radius:999px !important;background:rgba(255,255,255,.92) !important;box-shadow:0 8px 24px rgba(0,0,0,.12),0 1px 3px rgba(0,0,0,.06) !important;pointer-events:none !important;z-index:-1 !important}
[data-wk="headink"],[data-wk="headink"] *{color:#1C1C1E !important;font-weight:700 !important}
[data-wk="headdim"]{color:#8E8E93 !important}
[data-wk="chatback"] svg{stroke:#1C1C1E !important}
[data-wk="chathead"] [data-wk="avatar"]{border-radius:50% !important;position:relative !important;overflow:visible !important}
[data-wk="chathead"] [data-wk="avatar"] *{border-radius:50% !important}
[data-wk="chathead"] [data-wk="avatar"]::after{content:"" !important;position:absolute !important;right:-1px !important;bottom:-1px !important;width:10px !important;height:10px !important;border-radius:50% !important;background:#E5533D !important;box-shadow:0 0 0 2px #fff !important}
[data-wk="sameroom"],[data-wk="chatmore"]{width:32px !important;min-width:32px !important;height:32px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;background-color:transparent !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyNCAyNCc+PHBhdGggZD0nTTQgMTEgTDEyIDQgTDIwIDExIFYyMCBINFonIGZpbGw9J25vbmUnIHN0cm9rZT0nIzFDMUMxRScgc3Ryb2tlLXdpZHRoPScxLjcnIHN0cm9rZS1saW5lam9pbj0ncm91bmQnLz48L3N2Zz4=") center/22px no-repeat !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyNCAyNCc+PGNpcmNsZSBjeD0nNScgY3k9JzEyJyByPScxLjcnIGZpbGw9JyMxQzFDMUUnLz48Y2lyY2xlIGN4PScxMicgY3k9JzEyJyByPScxLjcnIGZpbGw9JyMxQzFDMUUnLz48Y2lyY2xlIGN4PScxOScgY3k9JzEyJyByPScxLjcnIGZpbGw9JyMxQzFDMUUnLz48L3N2Zz4=") center/22px no-repeat !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}

/* 头像：圆的，不加框 */
button[data-wk="avatar"],span[data-wk="avatar"]{border-radius:50% !important;box-shadow:none !important}
button[data-wk="avatar"] *,span[data-wk="avatar"] *,img[data-wk="avatar"]{border-radius:50% !important}

/* 气泡：胶囊，我的炭黑、他的纯白，都带一层柔和投影 */
[data-wk="bubble"][data-kind="text"]{border-radius:24px !important;padding:12px 18px !important;border:none !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:#2C2C30 !important;color:#fff !important;box-shadow:inset 0 0 0 1px rgba(255,255,255,.08),0 6px 16px rgba(0,0,0,.18) !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:#FFFFFF !important;color:#1C1C1E !important;box-shadow:0 6px 16px rgba(0,0,0,.08) !important}
[data-wk="bubble"][data-kind="text"]::before,[data-wk="bubble"][data-kind="text"]::after{content:none !important}

/* 时间：灰色小胶囊 */
[data-wk="time"] > span{display:inline-block !important;background:rgba(150,150,155,.35) !important;color:rgba(255,255,255,.95) !important;border-radius:999px !important;padding:3px 14px !important;border:none !important;font-size:11px !important}
/* 已读：白色小胶囊，已送达灰勾、已读红勾 */
[data-wk="meta"]{display:inline-flex !important;align-items:center !important;background:rgba(255,255,255,.85) !important;color:#8E8E93 !important;border-radius:999px !important;padding:1px 9px 1px 6px !important;font-size:10.5px !important}
[data-wk="meta"]::before{content:"" !important;width:12px !important;height:10px !important;margin-right:4px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxNCAxMic+PHBhdGggZD0nTTEuNSA2LjUgTDUgMTAgTDEyLjUgMicgZmlsbD0nbm9uZScgc3Ryb2tlPScjOEU4RTkzJyBzdHJva2Utd2lkdGg9JzInIHN0cm9rZS1saW5lY2FwPSdyb3VuZCcgc3Ryb2tlLWxpbmVqb2luPSdyb3VuZCcvPjwvc3ZnPg==") center/contain no-repeat !important}
[data-wk="meta"][data-read="1"]::before{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxNCAxMic+PHBhdGggZD0nTTEuNSA2LjUgTDUgMTAgTDEyLjUgMicgZmlsbD0nbm9uZScgc3Ryb2tlPScjRTU1MzNEJyBzdHJva2Utd2lkdGg9JzInIHN0cm9rZS1saW5lY2FwPSdyb3VuZCcgc3Ryb2tlLWxpbmVqb2luPSdyb3VuZCcvPjwvc3ZnPg==") center/contain no-repeat !important}
[data-wk="bubble"][data-kind="typing"]{background:#FFFFFF !important;border:none !important;border-radius:24px !important;box-shadow:0 6px 16px rgba(0,0,0,.08) !important}
[data-wk="typingdot"]{background:#8E8E93 !important}
[data-wk="narrink"]{background:rgba(255,255,255,.8) !important;border-radius:14px !important;color:#1C1C1E !important;padding:3px 10px !important}
[data-wk="sysnotetext"]{color:#8E8E93 !important}

/* 底栏：白胶囊包住加号、输入、回复；发送是外面单独一颗黑色圆键 */
[data-wk="composer"]{background:transparent !important;border-top:none !important;position:relative !important;z-index:2 !important;align-items:center !important;padding-left:24px !important;padding-right:14px !important;gap:6px !important}
[data-wk="composer"]::before{content:"" !important;position:absolute !important;left:10px !important;right:74px !important;top:4px !important;bottom:calc(env(safe-area-inset-bottom) * .4 + var(--composer-lift, 0px) - 6px) !important;border-radius:999px !important;background:rgba(255,255,255,.95) !important;box-shadow:0 8px 24px rgba(0,0,0,.12),0 1px 3px rgba(0,0,0,.06) !important;pointer-events:none !important;z-index:-1 !important}
[data-wk="chatinput"]{background:transparent !important;border:none !important;box-shadow:none !important;color:#1C1C1E !important}
[data-wk="chatinput"]::placeholder{color:#A1A1A6 !important}
[data-wk="chatplus"],[data-wk="chatreply"]{width:32px !important;min-width:32px !important;height:32px !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background-color:transparent !important;align-self:center !important}
[data-wk="chatplus"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyNCAyNCc+PHBhdGggZD0nTTEyIDUgVjE5IE01IDEyIEgxOScgc3Ryb2tlPScjMUMxQzFFJyBzdHJva2Utd2lkdGg9JzEuOCcgc3Ryb2tlLWxpbmVjYXA9J3JvdW5kJy8+PC9zdmc+") center/22px no-repeat !important}
[data-wk="chatreply"]{background:url("data:image/svg+xml;base64,") center/26px no-repeat !important;margin-right:14px !important}
[data-wk="send"]{order:99 !important;width:52px !important;min-width:52px !important;height:52px !important;border:none !important;border-radius:50% !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;box-shadow:0 8px 18px rgba(0,0,0,.25) !important;opacity:1 !important;align-self:center !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="chatplus"]:active,[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.9) !important}
[data-wk="chathead"] img,[data-wk="chathead"] [data-wk="avatar"],[data-wk="chathead"] [data-wk="avatar"] > *{border-radius:50% !important;overflow:hidden !important}
[data-wk="chathead"] button:has(> [data-wk="avatar"]){position:relative !important}
[data-wk="chathead"] button:has(> [data-wk="avatar"])::after{content:"" !important;position:absolute !important;left:30px !important;top:calc(50% + 12px) !important;width:10px !important;height:10px !important;border-radius:50% !important;background:#E5533D !important;box-shadow:0 0 0 2px #fff !important;z-index:3 !important}
